import sys
from collections import deque

MOD = 998244353


def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    A = [x - 1 for x in map(int, input().split())]

    # Remove all non-cycle vertices from the functional graph.
    indeg = [0] * N
    for v in A:
        indeg[v] += 1
    queue = deque(i for i in range(N) if indeg[i] == 0)
    on_cycle = [True] * N
    while queue:
        v = queue.popleft()
        on_cycle[v] = False
        w = A[v]
        indeg[w] -= 1
        if indeg[w] == 0:
            queue.append(w)

    # Every directed cycle must have one common value, so contract it.
    parent = list(range(N))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        x = find(x)
        y = find(y)
        if x != y:
            parent[y] = x

    for i in range(N):
        if on_cycle[i]:
            union(i, A[i])

    ids = {}
    comp = [0] * N
    for i in range(N):
        root = find(i)
        if root not in ids:
            ids[root] = len(ids)
        comp[i] = ids[root]

    count = len(ids)
    children = [[] for _ in range(count)]
    is_root = [True] * count
    for i in range(N):
        child = comp[i]
        par = comp[A[i]]
        if child != par:
            children[par].append(child)
            is_root[child] = False

    sys.setrecursionlimit(10000)

    # dp_v[k] is the number of assignments in v's subtree when
    # the value at v is at most k+1.
    def dfs(v):
        product = None
        for child in children[v]:
            child_dp = dfs(child)
            if product is None:
                product = child_dp
            else:
                for k in range(M):
                    product[k] = product[k] * child_dp[k] % MOD

        if product is None:
            product = [1] * M

        prefix = 0
        for k in range(M):
            prefix += product[k]
            if prefix >= MOD:
                prefix -= MOD
            product[k] = prefix
        return product

    answer = 1
    for v in range(count):
        if is_root[v]:
            answer = answer * dfs(v)[M - 1] % MOD

    print(answer)


if __name__ == "__main__":
    main()

