import sys
import math

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    mx = max(a)

    phi = list(range(mx + 1))
    for p in range(2, mx + 1):
        if phi[p] == p:
            for v in range(p, mx + 1, p):
                phi[v] -= phi[v] // p

    divisors = [[] for _ in range(mx + 1)]
    for d in range(1, mx + 1):
        for v in range(d, mx + 1, d):
            divisors[v].append(d)

    freq = [0] * (mx + 1)
    for x in a:
        freq[x] += 1
    values = [x for x in range(1, mx + 1) if freq[x]]

    # Frequently queried values are maintained directly. This also avoids
    # worst cases consisting of many copies of a highly composite number.
    heavy = [x for x in values if freq[x] * len(divisors[x]) > n]
    heavy_id = {x: i for i, x in enumerate(heavy)}

    # Divisor sums are only needed by values which are not maintained directly.
    active = bytearray(mx + 1)
    for x in values:
        if x not in heavy_id:
            for d in divisors[x]:
                active[d] = 1
    update_divisors = {}
    for x in values:
        update_divisors[x] = [d for d in divisors[x] if active[d]]

    divisor_sum = [0] * (mx + 1)
    heavy_sum = [0] * len(heavy)
    answer = 0
    weight = 1
    output = []

    for x in a:
        idx = heavy_id.get(x)
        if idx is None:
            q = 0
            for d in divisors[x]:
                q += phi[d] * divisor_sum[d]
            q %= MOD
        else:
            q = heavy_sum[idx]

        answer = (2 * answer + q) % MOD
        output.append(str(answer))

        for d in update_divisors[x]:
            z = divisor_sum[d] + weight
            if z >= MOD:
                z -= MOD
            divisor_sum[d] = z

        for i, h in enumerate(heavy):
            heavy_sum[i] = (heavy_sum[i] + weight * math.gcd(x, h)) % MOD

        weight = 2 * weight % MOD

    sys.stdout.write("\n".join(output))


if __name__ == "__main__":
    main()

