import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:n + 1]
    limit = max(a)

    # omega[x] is the number of prime factors of x, counted with multiplicity.
    omega = [0] * (limit + 1)
    is_prime = bytearray(b'\x01') * (limit + 1)
    if limit >= 0:
        is_prime[0] = 0
    if limit >= 1:
        is_prime[1] = 0

    for p in range(2, limit + 1):
        if is_prime[p]:
            if p * p <= limit:
                is_prime[p * p:limit + 1:p] = b'\x00' * (((limit - p * p) // p) + 1)
            power = p
            while power <= limit:
                for multiple in range(power, limit + 1, power):
                    omega[multiple] += 1
                if power > limit // p:
                    break
                power *= p

    nim_sum = 0
    for x in a:
        nim_sum ^= omega[x]

    print("Anna" if nim_sum else "Bruno")

if __name__ == "__main__":
    main()

