from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        pairs_by_right = [[] for _ in range(n + 1)]
        for pair_id, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            pairs_by_right[b].append((a, pair_id))

        largest_left = 0
        second_largest_left = 0
        largest_pair_id = -1
        extra = [0] * len(conflictingPairs)
        valid_subarrays = 0

        for right in range(1, n + 1):
            for left, pair_id in pairs_by_right[right]:
                if left > largest_left:
                    second_largest_left = largest_left
                    largest_left = left
                    largest_pair_id = pair_id
                elif left > second_largest_left:
                    second_largest_left = left

            valid_subarrays += right - largest_left
            if largest_pair_id != -1:
                extra[largest_pair_id] += largest_left - second_largest_left

        return valid_subarrays + max(extra)

