from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        largest = second = 0
        largest_id = -1
        gain = [0] * len(conflictingPairs)
        valid = 0

        for right in range(1, n + 1):
            for left, pair_id in by_right[right]:
                if left > largest:
                    second = largest
                    largest = left
                    largest_id = pair_id
                elif left > second:
                    second = left

            valid += right - largest
            if largest_id != -1:
                gain[largest_id] += largest - second

        return valid + max(gain)

