import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    n = next(it); m = next(it); q = next(it)
    edges = []
    for _ in range(m):
        edges.append((next(it)-1, next(it)-1, next(it)))

    queries = []
    deleted = [False] * m
    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it) - 1
            queries.append((1, e))
            deleted[e] = True
        else:
            queries.append((2, next(it)-1, next(it)-1))

    INF = 10**30
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for e, (a, b, c) in enumerate(edges):
        if not deleted[e]:
            dist[a][b] = dist[b][a] = c

    # Floyd-Warshall; only one triangle is needed because the graph is undirected.
    for k in range(n):
        dk = dist[k]
        for i in range(n):
            di = dist[i]
            dik = di[k]
            if dik == INF:
                continue
            for j in range(i + 1, n):
                v = dik + dk[j]
                if v < di[j]:
                    di[j] = v
                    dist[j][i] = v

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            v = dist[query[1]][query[2]]
            answers.append(-1 if v == INF else v)
        else:
            a, b, c = edges[query[1]]
            # A non-improving edge cannot change any shortest distance.
            if c >= dist[a][b]:
                continue
            old_a = dist[a][:]
            old_b = dist[b][:]
            for i in range(n):
                di = dist[i]
                via_a = old_a[i] + c
                via_b = old_b[i] + c
                for j in range(i + 1, n):
                    v1 = via_a + old_b[j]
                    v2 = via_b + old_a[j]
                    v = v1 if v1 < v2 else v2
                    if v < di[j]:
                        di[j] = v
                        dist[j][i] = v

    sys.stdout.write('\n'.join(map(str, reversed(answers))))

if __name__ == "__main__":
    main()

