class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 1_000_000_007
        m = len(s)

        combinations = [[0] * (m + 1) for _ in range(m + 1)]
        combinations[0][0] = 1
        for length in range(1, m + 1):
            combinations[length][0] = combinations[length][length] = 1
            for chosen in range(1, length):
                combinations[length][chosen] = (
                    combinations[length - 1][chosen - 1]
                    + combinations[length - 1][chosen]
                ) % MOD

        good_popcount = [False] * (m + 1)
        for count in range(1, m + 1):
            value = count
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            good_popcount[count] = steps <= k - 1

        answer = 0
        prefix_ones = 0

        for index, bit in enumerate(s):
            if bit == '1':
                remaining = m - index - 1

                # Choosing 0 here makes the constructed number strictly less
                # than n. The remaining bits can then be chosen freely.
                for suffix_ones in range(remaining + 1):
                    total_ones = prefix_ones + suffix_ones
                    if good_popcount[total_ones]:
                        answer += combinations[remaining][suffix_ones]

                answer %= MOD
                prefix_ones += 1

        return answer

