class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 1_000_000_007
        m = len(s)

        # C[a][b] modulo MOD.
        comb = [[0] * (m + 1) for _ in range(m + 1)]
        comb[0][0] = 1
        for a in range(1, m + 1):
            comb[a][0] = comb[a][a] = 1
            for b in range(1, a):
                comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD

        good = [False] * (m + 1)
        for ones in range(1, m + 1):
            value = ones
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            good[ones] = steps <= k - 1

        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = m - i - 1
                # Put 0 here (making the number smaller), then choose its suffix.
                for suffix_ones in range(remaining + 1):
