    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
        ni=P+di; nj=Q+dj
        if 0<=ni<H and 0<=nj<W:
            k=ni*W+nj
            if not seen[k]:
                seen[k]=1
                heapq.heappush(hp,(A[ni][nj],ni,nj))
    while hp:
        s,i,j=heapq.heappop(hp)
        if s*X>=strength:
