import sys

def main():
    s = sys.stdin.buffer.readline().strip()
    r = s[::-1]
    n = len(s)

    # Prefix function for the reversed string.
    pi = [0] * n
    j = 0
    for i in range(1, n):
        c = r[i]
        while j and c != r[j]:
            j = pi[j - 1]
        if c == r[j]:
            j += 1
        pi[i] = j

    # Find the longest suffix of s that is also a prefix of r.
    # Such a suffix is exactly a palindromic suffix of s.
    j = 0
    for c in s:
        while j and (j == n or c != r[j]):
            j = pi[j - 1]
        if c == r[j]:
            j += 1

    sys.stdout.buffer.write(s + r[j:] + b'\n')

if __name__ == '__main__':
    main()

