import sys

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    A = list(map(int, input().split()))
    B = list(map(int, input().split()))

    if M == 2:
        print(0 if A == B else -1)
        return

    offset = 0
    displacement = []
    for i in range(N):
        if i > 0:
            if A[i - 1] < A[i]:
                if B[i - 1] > B[i]:
                    offset += 1
            else:
                if B[i - 1] < B[i]:
                    offset -= 1
        displacement.append(B[i] + M * offset - A[i])

    ordered = sorted(displacement)
    median = ordered[N // 2]
    q = (-median) // M
    ans = min(
        sum(abs(x + M * t) for x in displacement)
        for t in (q, q + 1)
    )
    print(ans)

