        pos += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    pivot_cols = []
    rank = 0
    for col in range(n):
        pivot = -1
        for i in range(rank, n):
            if (rows[i] >> col) & 1:
                pivot = i
                break
        if pivot < 0:
            continue
        rows[rank], rows[pivot] = rows[pivot], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivot_cols.append(col)
        rank += 1

    is_pivot = [False] * n
    for col in pivot_cols:
