from typing import List


class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Diagonal directions in clockwise order.
        directions = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        answer = 0

        def traversal(step: int, size: int):
            if step > 0:
                return range(size)
            return range(size - 1, -1, -1)

        for index, (dr, dc) in enumerate(directions):
            # Longest valid straight segment ending at each cell while moving
            # in the current direction.
            straight = [[0] * m for _ in range(n)]

            for r in traversal(dr, n):
                for c in traversal(dc, m):
                    value = grid[r][c]
