class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half_len = (n + 1) // 2

        # powers[i] = 10^i mod k
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        # Contribution modulo k of each digit in the palindrome's first half.
        contribution = [0] * half_len
        for i in range(half_len):
            mirror = n - 1 - i
            if i == mirror:
                contribution[i] = powers[i]
            else:
                contribution[i] = (powers[i] + powers[mirror]) % k

        # possible[i] is a bit mask of residues obtainable using positions
        # i through half_len - 1.
        possible = [0] * (half_len + 1)
        possible[half_len] = 1  # Only residue 0 is possible with no digits.

        for i in range(half_len - 1, -1, -1):
            tail_mask = possible[i + 1]
            mask = 0
            coefficient = contribution[i]
            for tail_residue in range(k):
                if tail_mask & (1 << tail_residue):
                    for digit in range(10):
                        residue = (tail_residue + digit * coefficient) % k
                        mask |= 1 << residue
            possible[i] = mask

        # Greedily choose the largest digit that still permits a completion.
        half = []
        current_residue = 0
        for i in range(half_len):
            minimum = 1 if i == 0 else 0
            coefficient = contribution[i]

            for digit in range(9, minimum - 1, -1):
                new_residue = (current_residue + digit * coefficient) % k
                required_tail = (-new_residue) % k
                if possible[i + 1] & (1 << required_tail):
                    half.append(str(digit))
                    current_residue = new_residue
                    break

        left = ''.join(half)
        if n % 2:
            return left + left[-2::-1]
        return left + left[::-1]

