import sys

def main():
    input = sys.stdin.readline
    n, k = map(int, input().split())
    funcs = [tuple(map(int, input().split())) for _ in range(n)]
    # Process functions from innermost to outermost.
    funcs.sort(key=lambda t: (t[0] - 1) / t[1])

    dp = [-1] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        upper = min(k, n)  # descending update ensures each function is used once
        for j in range(upper, 0, -1):
            if dp[j - 1] >= 0:
                v = a * dp[j - 1] + b
                if v > dp[j]:
                    dp[j] = v
    print(dp[k])

