class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        answer = len(s)  # Delete every character.

        for target in range(1, max(counts) + 1):
            dp = [10**9] * 27
            dp[0] = 0

            for i in range(26):
                # Make this letter absent, or make its frequency target.
                individual_cost = min(
                    counts[i],
                    abs(counts[i] - target)
                )
                dp[i + 1] = min(dp[i + 1], dp[i] + individual_cost)

                # Use changes from this letter to help the next letter.
                if i < 25 and counts[i + 1] < target:
                    deficit = target - counts[i + 1]

                    if counts[i] >= target:
                        excess = counts[i] - target
                    else:
                        # Make this letter absent and change its occurrences.
                        excess = counts[i]

                    pair_cost = max(excess, deficit)
                    dp[i + 2] = min(dp[i + 2], dp[i] + pair_cost)

            answer = min(answer, dp[26])

        return answer

