class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        parent[0] = n
        order = [0]
        for u in order:
            for v, _ in graph[u]:
                if parent[v] == -1:
                    parent[v] = u
                    order.append(v)

        # free[u]: optimum if the edge from u to its parent is not retained.
        # used[u]: optimum if that edge is retained, leaving k-1 child slots.
        free = [0] * n
        used = [0] * n

        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += free[v]
                    gain = w + used[v] - free[v]
                    if gain > 0:
                        gains.append(gain)

            gains.sort(reverse=True)
            free[u] = base + sum(gains[:k])
            used[u] = base + sum(gains[:k - 1])

        return free[0]

