def half_scores(arr):
    low=[]  # max heap
    high=[] # min heap
    sl=sh=0
    res=[0]*(len(arr)+1)
    for t,x in enumerate(arr,1):
        if high and x>=high[0]:
            heapq.heappush(high,x); sh+=x
        else:
            heapq.heappush(low,-x); sl+=x
        target=t//2
        while len(low)>target:
            y=-heapq.heappop(low); sl-=y
            heapq.heappush(high,y); sh+=y
        while len(low)<target:
            y=heapq.heappop(high); sh-=y
            heapq.heappush(low,-y); sl+=y
        if t%2==0:
            res[t]=sh-sl
    return res

