class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t: str):
            if not t:
                return list(range(n + 1))

            m = len(t)
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = prefix[j - 1]
                if t[i] == t[j]:
                    j += 1
                prefix[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = prefix[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = prefix[j - 1]
            return result

        occ_a = occurrences(a)
        occ_b = occurrences(b)
        occ_c = occurrences(c)

        # For every occurrence of b, retain the latest compatible
        # occurrence of a, since that gives the shortest possible window.
        pairs = []
        ai = 0
        latest_a = -1
        for b_start in occ_b:
            while ai < len(occ_a) and occ_a[ai] + len(a) <= b_start:
                latest_a = occ_a[ai]
                ai += 1
            if latest_a >= 0:
                pairs.append((b_start + len(b), latest_a))

        answer = n + 1
        pair_i = 0
        latest_start = -1

        # Among all a-b pairs ending before c, the one with the latest
        # starting position produces the shortest window ending at this c.
        for c_start in occ_c:
            while pair_i < len(pairs) and pairs[pair_i][0] <= c_start:
                latest_start = max(latest_start, pairs[pair_i][1])
                pair_i += 1
            if latest_start >= 0:
                answer = min(answer, c_start + len(c) - latest_start)

        return -1 if answer == n + 1 else answer

