    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    pos = 2
    for _ in range(m):
        x, y, z = data[pos] - 1, data[pos + 1] - 1, data[pos + 2]
        pos += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    xor_dist = [-1] * n
    answer = [0] * n

    for start in range(n):
        if xor_dist[start] != -1:
            continue

        xor_dist[start] = 0
        stack = [start]
        component = []

        while stack:
            v = stack.pop()
            component.append(v)
            for to, z in graph[v]:
                required = xor_dist[v] ^ z
                if xor_dist[to] == -1:
                    xor_dist[to] = required
                    stack.append(to)
                elif xor_dist[to] != required:
                    print(-1)
                    return

        bit_counts = [0] * 30
        for v in component:
            value = xor_dist[v]
            for bit in range(30):
                bit_counts[bit] += (value >> bit) & 1

        base = 0
        size = len(component)
        for bit in range(30):
            if bit_counts[bit] * 2 > size:
                base |= 1 << bit

        for v in component:
            answer[v] = xor_dist[v] ^ base

    print(*answer)

if __name__ == "__main__":
    main()

