import sys

def solve(n, a, b):
    x = [i for i, c in enumerate(a) if c == '1']
    z = [i for i, c in enumerate(b) if c == '1']
    if len(z) > len(x):
        return -1
    m, q = len(x), len(z)
    cuts = [0]
    s = 0
    for j in range(q - 1):
        e = s
        need = z[j + 1] - z[j]
        while e + 1 < m and x[e + 1] - x[e] < need:
            e += 1
        if e + 1 == m:
            return -1
        s = e + 1
        cuts.append(s)
    cuts.append(m)

    d = []
    for j in range(q):
        d.extend(x[i] - z[j] for i in range(cuts[j], cuts[j + 1]))
    if any(d[i] > d[i + 1] for i in range(m - 1)):
        return -1

    k = max(map(abs, d))
    while True:
        exceptional = 0
        for j in range(q):
            if any((k - d[i]) & 1 for i in range(cuts[j], cuts[j + 1])):
                exceptional += 1
        if exceptional <= k:
            return k
        k += 1

