import sys

def within_k(s, t, k):
    p = 0
    limit = min(len(s), len(t))
    while p < limit and s[p] == t[p]:
        p += 1
    s = s[p:]
    t = t[p:]

    q = 0
    limit = min(len(s), len(t))
    while q < limit and s[len(s) - 1 - q] == t[len(t) - 1 - q]:
        q += 1
    if q:
        s = s[:-q]
        t = t[:-q]

    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if n == 0 or m == 0:
        return max(n, m) <= k

    offset = k + 1
    width = 2 * k + 3
    prev = [-1] * width

    x = 0
    while x < n and x < m and s[x] == t[x]:
        x += 1
    prev[offset] = x
    if x == n and x == m:
        return True

    for used in range(1, k + 1):
        cur = [-1] * width
        for diagonal in range(-used, used + 1):
            best = -1

            x = prev[offset + diagonal]
            if x >= 0:
                y = x + diagonal
                if x < n and y < m:
                    best = x + 1

            x = prev[offset + diagonal - 1]
            if x >= 0:
                y = x + diagonal - 1
                if y < m and x > best:
                    best = x

            x = prev[offset + diagonal + 1]
            if x >= 0 and x < n and x + 1 > best:
                best = x + 1

            if best < 0:
                continue
            y = best + diagonal
            if best > n or y < 0 or y > m:
                continue

            while best < n and y < m and s[best] == t[y]:
                best += 1
                y += 1
            cur[offset + diagonal] = best
            if best == n and y == m:
                return True
        prev = cur

    return False


