import sys

MOD = 998244353
ROOT = 3


def ntt(a, inverse=False):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        root = pow(ROOT, (MOD - 1) // length, MOD)
        if inverse:
            root = pow(root, MOD - 2, MOD)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            end = start + half
            for i in range(start, end):
                u = a[i]
                v = a[i + half] * w % MOD
                a[i] = (u + v) % MOD
                a[i + half] = (u - v) % MOD
                w = w * root % MOD
        length <<= 1

    if inverse:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


def convolution(a, b):
    if min(len(a), len(b)) < 48:
        result = [0] * (len(a) + len(b) - 1)
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    result[i + j] = (result[i + j] + x * y) % MOD
        return result

    size = 1
    needed = len(a) + len(b) - 1
    while size < needed:
        size <<= 1
    a = a + [0] * (size - len(a))
    b = b + [0] * (size - len(b))
    ntt(a)
    ntt(b)
    for i in range(size):
        a[i] = a[i] * b[i] % MOD
    ntt(a, True)
    return a


def main():
    input = sys.stdin.readline
    n = int(input())
    s = input().strip()

    # The first cut and the last cut must be crossed backwards.
    if s[0] != 'B' or s[-1] != 'W':
        print(0)
        return

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (n + 1)
    inv_fact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    # a[i] is the number of W's before the (i+1)-st B.
    a = [0] * n
    whites = blacks = 0
    for ch in s:
        if ch == 'W':
            whites += 1
        else:
            blacks += 1
            if blacks >= 2:
                a[blacks - 1] = whites

    valid = [False] * n
    for i in range(1, n):
        valid[i] = a[i] >= i

    dp = [0] * n
    query = [0] * n
    dp[0] = 1
    for i in range(1, n):
        if valid[i]:
            query[i] = fact[a[i]]

    sys.setrecursionlimit(1_000_000)

    # CDQ computes
    # dp[i] = -1/(a[i]-i)! * sum_{j<i} dp[j] (a[i]-j)!.
    def cdq(left, right):
        if right - left == 1:
            if valid[left]:
                dp[left] = -query[left] * inv_fact[a[left] - left] % MOD
            return

        middle = (left + right) >> 1
        cdq(left, middle)

        targets = [i for i in range(middle, right) if valid[i]]
        if targets:
            maximum = max(a[i] for i in targets)
            product = convolution(dp[left:middle], fact[:maximum - left + 1])
            for i in targets:
                query[i] = (query[i] + product[a[i] - left]) % MOD

        cdq(middle, right)

    if n > 1:
        cdq(1, n)

    answer = fact[n]
    for i in range(1, n):
        if valid[i]:
            answer = (answer + dp[i] * fact[n - i]) % MOD
    print(answer)


if __name__ == '__main__':
    main()

