def main():
    N = int(sys.stdin.readline())
    limit = math.isqrt(N)

    is_prime = bytearray(b'\x01') * (limit + 1)
    is_prime[0] = 0
    if limit >= 1:
        is_prime[1] = 0

    for p in range(2, math.isqrt(limit) + 1):
        if is_prime[p]:
            start = p * p
            is_prime[start:limit + 1:p] = b'\x00' * (((limit - start) // p) + 1)

    primes = [p for p in range(2, limit + 1) if is_prime[p]]

    answer = 0

    # Numbers of the form p^2 * q^2 for distinct primes p and q.
    right = len(primes) - 1
    for left, p in enumerate(primes):
        while right > left and p * primes[right] > limit:
            right -= 1
        if right <= left:
            break
        answer += right - left

    # Numbers of the form p^8.
    for p in primes:
        if p ** 8 <= N:
            answer += 1
        else:
            break

    print(answer)


