    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)

        # For each index, bit s is set when a subset of the applicable
        # query values seen so far has sum s.
        possible = [1] * n
        completed = [value == 0 for value in nums]
        remaining = sum(not state for state in completed)

        if remaining == 0:
            return 0

        masks = [(1 << (value + 1)) - 1 for value in nums]

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                if completed[i]:
                    continue

                possible[i] |= (possible[i] << value) & masks[i]
                if possible[i] & (1 << nums[i]):
                    completed[i] = True
                    remaining -= 1

            if remaining == 0:
