class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        limit = 10000
        is_prime = bytearray(b'\x01') * limit
        is_prime[0:2] = b'\x00\x00'
        for p in range(2, 100):
            if is_prime[p]:
                is_prime[p * p:limit:p] = b'\x00' * (((limit - 1 - p * p) // p) + 1)

        if is_prime[n] or is_prime[m]:
            return -1

        digits = len(str(n))
        low = 1 if digits == 1 else 10 ** (digits - 1)
        high = 10 ** digits
        dist = [10**30] * high
        dist[n] = n
        pq = [(n, n)]
        powers = [10 ** i for i in range(digits)]

        while pq:
            cost, x = heapq.heappop(pq)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            for place in powers:
                digit = (x // place) % 10

                if digit < 9:
                    y = x + place
                    if y < high and not is_prime[y]:
                        new_cost = cost + y
                        if new_cost < dist[y]:
                            dist[y] = new_cost
                            heapq.heappush(pq, (new_cost, y))

                if digit > 0:
                    y = x - place
                    if y >= low and not is_prime[y]:
                        new_cost = cost + y
                        if new_cost < dist[y]:
                            dist[y] = new_cost
                            heapq.heappush(pq, (new_cost, y))

        return -1

