from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)

        is_target = [False] * n
        for index in targetIndices:
            is_target[index] = True

        # dp[j] is the minimum number of target indices used by an
        # embedding of pattern[:j] in the processed prefix of source.
        inf = m + 1
        dp = [inf] * (m + 1)
        dp[0] = 0

        for i, char in enumerate(source):
            cost = 1 if is_target[i] else 0
            for j in range(m - 1, -1, -1):
                if char == pattern[j]:
                    candidate = dp[j] + cost
                    if candidate < dp[j + 1]:
                        dp[j + 1] = candidate

        # Every targeted position not needed by the chosen embedding can
        # be removed while preserving that embedding as a subsequence.
        return len(targetIndices) - dp[m]

