from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        reverse_graph = [[] for _ in range(n)]
        weights = []

        for source, destination, weight in edges:
            reverse_graph[destination].append((source, weight))
            weights.append(weight)

        weights = sorted(set(weights))

        def feasible(limit: int) -> bool:
            visited = bytearray(n)
            visited[0] = 1
            stack = [0]
            reached = 1

            while stack:
                node = stack.pop()
                for neighbor, weight in reverse_graph[node]:
                    if weight <= limit and not visited[neighbor]:
                        visited[neighbor] = 1
                        reached += 1
                        stack.append(neighbor)

            return reached == n

        if not feasible(weights[-1]):
            return -1

        left, right = 0, len(weights) - 1
        while left < right:
            middle = (left + right) // 2
            if feasible(weights[middle]):
                right = middle
            else:
                left = middle + 1

        return weights[left]

