from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = 10**30

        # A state stores the colors of the latest house painted from
        # the left and the latest house painted from the right.
        dp = {
            (left, right): cost[0][left] + cost[n - 1][right]
            for left in range(3)
            for right in range(3)
            if left != right
        }

        for i in range(1, n // 2):
            right_index = n - 1 - i
            next_dp = {}

            for left in range(3):
                for right in range(3):
                    # These two houses are equidistant from the ends.
                    if left == right:
                        continue

                    best_previous = INF
                    for (prev_left, prev_right), previous_cost in dp.items():
                        if left != prev_left and right != prev_right:
                            best_previous = min(best_previous, previous_cost)

                    next_dp[(left, right)] = (
                        best_previous
                        + cost[i][left]
                        + cost[right_index][right]
                    )

            dp = next_dp

        return min(dp.values())

