import sys

def main():
    input = sys.stdin.readline
    N, W = map(int, input().split())
    cols = [[] for _ in range(W)]
    for i in range(N):
        x, y = map(int, input().split())
        cols[x-1].append((y, i))

    rank = [0] * N
    for col in cols:
        col.sort()
        for k, (_, idx) in enumerate(col):
            rank[idx] = k

    m = min(map(len, cols))
    disappear = [0] * m
    for col in cols:
        for k in range(m):
            if col[k][0] > disappear[k]:
                disappear[k] = col[k][0]

    Q = int(input())
    ans = []
    for _ in range(Q):
        t, a = map(int, input().split())
        k = rank[a-1]
        if k < m and disappear[k] <= t:
            ans.append("No")
        else:
            ans.append("Yes")
    print('\n'.join(ans))

if __name__ == "__main__":
    main()

