class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = {'a': 0, 'e': 1, 'i': 2, 'o': 3, 'u': 4}
        answer = 0
        n = len(word)

        for left in range(n):
            mask = 0
            consonants = 0

            for right in range(left, n):
                ch = word[right]
                if ch in vowels:
                    mask |= 1 << vowels[ch]
                else:
                    consonants += 1

                if consonants > k:
                    break
                if consonants == k and mask == 31:
                    answer += 1

        return answer

