from typing import List

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        point_set = {tuple(point) for point in points}
        answer = -1
        n = len(points)

        for i in range(n):
            x1, y1 = points[i]
            for j in range(i + 1, n):
                x2, y2 = points[j]

                # Opposite corners must differ in both coordinates.
                if x1 == x2 or y1 == y2:
                    continue

                left, right = sorted((x1, x2))
                bottom, top = sorted((y1, y2))

                corners = (
                    (left, bottom),
                    (left, top),
                    (right, bottom),
                    (right, top),
                )
                if not all(corner in point_set for corner in corners):
                    continue

                # A valid rectangle has exactly its four corners in its
                # closed region; any fifth point is inside or on the border.
                contained = sum(
                    left <= x <= right and bottom <= y <= top
                    for x, y in points
                )
                if contained == 4:
                    area = (right - left) * (top - bottom)
                    answer = max(answer, area)

        return answer

